import 'package:flutter/material.dart';
void main()=>runApp(const MaterialApp(home:Wallet(),debugShowCheckedModeBanner:false));
class Wallet extends StatefulWidget{const Wallet({super.key});@override State<Wallet> createState()=>_WalletState();}
class _WalletState extends State<Wallet>{double balance=125;int tab=0;final tx=<String>['Welcome demo credit +\$125.00'];final amount=TextEditingController();
void topup(){amount.clear();showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Demo top-up'),content:TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),TextButton(onPressed:(){final v=double.tryParse(amount.text);if(v==null||v<=0)return;setState(()=>balance+=v);tx.insert(0,'Demo top-up +\$$v');Navigator.pop(context);},child:const Text('Add'))]));}
@override Widget build(BuildContext c){return Scaffold(backgroundColor:const Color(0xff071321),appBar:AppBar(title:const Text('VESORA PAY')),body:tab==0?ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:const Color(0xff12324d),borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('DEMO WALLET BALANCE'),const SizedBox(height:12),Text('\$${balance.toStringAsFixed(2)}',style:const TextStyle(fontSize:32,fontWeight:FontWeight.bold)),const Text('Prototype · Simulated funds')]),),const SizedBox(height:20),Row(children:[Expanded(child:action('Add money',Icons.add,topup)),Expanded(child:action('Send',Icons.arrow_upward,()=>message('Send is demo-only'))),Expanded(child:action('Receive',Icons.call_received,()=>message('Demo wallet ID: VESORA-DEMO-001')))]),const SizedBox(height:20),const Text('Recent activity',style:TextStyle(fontSize:18)),...tx.map((s)=>ListTile(leading:const Icon(Icons.swap_horiz,color:Colors.lightBlue),title:Text(s))),const Text('No real money is connected.',style:TextStyle(color:Colors.white54))]):ListView(children:tab==1?tx.map((s)=>ListTile(title:Text(s),leading:const Icon(Icons.history))).toList():const [ListTile(title:Text('Demo user'),subtitle:Text('Vesora Pay prototype'))]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [NavigationDestination(icon:Icon(Icons.wallet),label:'Wallet'),NavigationDestination(icon:Icon(Icons.history),label:'Activity'),NavigationDestination(icon:Icon(Icons.person),label:'Profile')]);}
Widget action(String label,IconData icon,VoidCallback cb)=>TextButton(onPressed:cb,child:Column(children:[Icon(icon),Text(label)]));void message(String s)=>showDialog(context:context,builder:(_)=>AlertDialog(content:Text(s),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Close'))]));}
